<?php
require_once __DIR__.'/../includes/security.php';
require __DIR__.'/../includes/db.php';
require_admin();
$id=(int)($_GET['id']??0);$type=$_GET['type']??'invoice';
if(!in_array($type,['invoice','packing'],true)){http_response_code(400);exit('Jenis cetak tidak valid.');}
$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();
if(!$o){http_response_code(404);exit('Pesanan tidak ditemukan.');}
$s=$pdo->prepare('SELECT product_name,price,quantity,price*quantity AS line_total FROM order_items WHERE order_id=? ORDER BY id');$s->execute([$id]);$items=$s->fetchAll();
$packing=$type==='packing';
